begin;
create extension if not exists pgtap with schema extensions;
select plan(18);
select has_column('public', 'credit_accounts', 'version', 'credit account has an optimistic version');
select function_returns('public', 'apply_approved_credit_adjustment', array['uuid'], 'jsonb', 'credit adjustment apply RPC signature');
select ok((select p.prosecdef from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'apply_approved_credit_adjustment'), 'credit adjustment apply is security definer');
select ok(has_function_privilege('authenticated', 'public.apply_approved_credit_adjustment(uuid)', 'EXECUTE'), 'authenticated can apply approved adjustment');
select ok(not has_function_privilege('anon', 'public.apply_approved_credit_adjustment(uuid)', 'EXECUTE'), 'anon cannot apply adjustment');
select ok(not has_function_privilege('service_role', 'public.apply_approved_credit_adjustment(uuid)', 'EXECUTE'), 'service role cannot call operator adjustment directly');
select ok((select pg_get_functiondef('public.apply_approved_credit_adjustment(uuid)'::regprocedure) like '%request_row.status <> ''approved''%'), 'only approved credit adjustments can apply');
select ok((select pg_get_functiondef('public.apply_approved_credit_adjustment(uuid)'::regprocedure) like '%request_row.expected_version%'), 'expected account version is required');
select ok((select pg_get_functiondef('public.apply_approved_credit_adjustment(uuid)'::regprocedure) like '%for update%'), 'approval and account rows are locked');
select ok((select pg_get_functiondef('public.apply_approved_credit_adjustment(uuid)'::regprocedure) like '%insert into public.credit_ledger_entries%'), 'adjustment appends a ledger entry');
select ok((select pg_get_functiondef('public.apply_approved_credit_adjustment(uuid)'::regprocedure) like '%version = next_version%'), 'account version increments');
select ok((select pg_get_functiondef('public.apply_approved_credit_adjustment(uuid)'::regprocedure) like '%approved-credit-adjust:%'), 'adjustment idempotency key is domain separated');
select ok((select pg_get_functiondef('public.apply_approved_credit_adjustment(uuid)'::regprocedure) like '%credit.adjust.applied%'), 'adjustment appends audit event');
select ok((select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%admin.account.activated%' and (select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%workspace.activation.requested%' and (select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%credit.adjust.applied%' and (select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%publish.retry.applied%', 'all existing audit actions remain allowed');
select ok((select pg_get_functiondef('public.apply_approved_credit_adjustment(uuid)'::regprocedure) like '%replay_summary%jsonb_object_keys%'), 'replay validates the stored approval summary');
select ok((select pg_get_functiondef('public.apply_approved_credit_adjustment(uuid)'::regprocedure) like '%direction%amount%reason_code%'), 'audit records safe adjustment facts');
select ok((select pg_get_functiondef('public.list_operator_billing_overview(uuid,integer)'::regprocedure) like '%account.version%'), 'billing read exposes account version');
select ok((select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%document.version.draft_created%' and (select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%document.version.reviewed%' and (select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%document.version.activated%', 'document version audit actions remain allowed');
select * from finish();
rollback;
